    let severity: String

    var debugDescription: String {
        return "[\(severity)] Bug #\(id)"
    }
}

let report = BugReport(id: 101, severity: "HIGH")
print(report.debugDescription)

import Foundation

struct BreakpointConditionEvaluator {
    static func shouldPause(iteration: Int, target: Int) -> Bool {
        return iteration == target
    }
}

let pause = BreakpointConditionEvaluator.shouldPause(iteration: 5, target: 5)
print("Should pause: \(pause)")

import Foundation

final class DebugLoggerAction {
    private(set) var messages: [String] = []

    func log(message: String) {
        messages.append(message)
    }

    func lastLog() -> String? {
        return messages.last
    }
}

let logger = DebugLoggerAction()
logger.log(message: "Breakpoint hit at line 42")
print("Logged: \(logger.lastLog() ?? "none")")
